WITH unpacked AS (SELECT id, customer_id, created_at, coupon_codes, ship_to, attributes, SIZE(attributes) AS num_attributes, EXISTS(items, x -> x.price > 100) AS has_premium_item, SIZE(FILTER(items, x -> x.qty >= 3)) AS bulk_lines, ARRAY_MAX(TRANSFORM(items, x -> x.price)) AS max_item_price, attributes['utm_source'] AS utm_source FROM carts) SELECT customer_id, CASE WHEN bulk_lines >= 3 THEN 'LARGE' ELSE 'SMALL' END AS bulk_lines_tier, COUNT(DISTINCT utm_source) AS distinct_utm_sources, COUNT(DISTINCT utm_source) AS distinct_utm_sources_2, GROUPING_ID() AS grouping_level FROM unpacked GROUP BY GROUPING SETS ((customer_id, CASE WHEN bulk_lines >= 3 THEN 'LARGE' ELSE 'SMALL' END), (customer_id), ());
